select "id", "scope_id", "name_ct", "phone_ct", "address_ct", "memo_ct", "email_ct", "company_ct" from "test_r9_verify_main"."customers" where ("test_r9_verify_main"."customers"."scope_id" = $1 and "customers"."id" in (
    with matched as materialized (
      select "c"."row_id" from (
    select "picked"."row_id","proof"."tokens_ef1d32a52e2ce103","proof"."pos_salt_ef1d32a52e2ce103","proof"."pos_len_ef1d32a52e2ce103","proof"."pos_stamps_ef1d32a52e2ce103","proof"."pos_offsets_ef1d32a52e2ce103"
    from (
      select "row_id" from "test_r9_verify_main"."customers_seal_index" as "c"
      where "c"."scope_id"=$2 and "c"."tokens_ef1d32a52e2ce103" @> $3::bigint[]
      order by "c"."row_id" offset 0
    ) as "picked"
    cross join lateral (
      select "tokens_ef1d32a52e2ce103","pos_salt_ef1d32a52e2ce103","pos_len_ef1d32a52e2ce103","pos_stamps_ef1d32a52e2ce103","pos_offsets_ef1d32a52e2ce103" from "test_r9_verify_main"."customers_seal_index" as "lookup"
      where "lookup"."scope_id"=$4 and "lookup"."row_id"="picked"."row_id" offset 0
    ) as "proof"
    order by "picked"."row_id" offset 0
  ) as "c" where ("c"."tokens_ef1d32a52e2ce103" @> $5::bigint[] and coalesce("test_r9_verify_main"."sealql_match_positions"($6::bytea[],$7::integer[],$8,
        "c"."pos_len_ef1d32a52e2ce103","c"."pos_salt_ef1d32a52e2ce103","c"."pos_stamps_ef1d32a52e2ce103","c"."pos_offsets_ef1d32a52e2ce103",$9),false)) order by "c"."row_id" limit $10
    ) select row_id from matched
  )) order by "test_r9_verify_main"."customers"."id" asc limit $11

